/** DES-RTI-PREREQ — Giao việc → RMMS BFF `POST /tasks` → TaskService.
 *  `VITE_RMMS_TASK_INTEGRATE_UNLOCK`: `0` hide · `1` force on · unset = on.
 */
const PREREQ_TOOLTIP = 'Đang triển khai Platform Task';

export function isPlatformTaskIntegrationReady(): boolean {
  // `0` hides the CTA. `1` or unset leaves it on (dev default; main required `1`).
  if (import.meta.env.VITE_RMMS_TASK_INTEGRATE_UNLOCK === '0') return false;
  return true;
}

export function platformTaskPrereqTooltip(): string {
  return PREREQ_TOOLTIP;
}
