import React, { useCallback, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { Button } from '@linm-soft-org/linm-web-common-components';
import { ChatSectionHost } from '../../components/ChatSectionHost/ChatSectionHost';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import { useShellPageTitle } from '../../router/useShellPageTitle';
import { isPlatformTaskIntegrationReady } from '../../utils/platformTaskPrereq';
import { platformTaskListHref } from '../../utils/platformTaskUrls';
import styles from './RmmsTaskIntegrateVerifyPage.module.css';

const TEST_ID = 'rmms-task-integrate-verify';

const RmmsTaskIntegrateVerifyPage: React.FC = () => {
  useShellPageTitle('RMMS Task Integrate — Verify');
  const taskListHref = platformTaskListHref();
  const navigate = useInAppNavigate();
  const [searchParams] = useSearchParams();
  const [taskIdInput, setTaskIdInput] = useState(searchParams.get('taskId') ?? '');
  const [mountedTaskId, setMountedTaskId] = useState(searchParams.get('taskId') ?? '');

  const onParcelNavigate = useCallback(
    (path: string) => {
      if (/^https?:\/\//i.test(path)) {
        window.location.assign(path);
        return;
      }
      navigate(path);
    },
    [navigate],
  );

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <h1 className={styles.title}>rmms-task-integrate</h1>
      <div className={styles.meta}>
        <span>
          <strong>packKind:</strong> platform integration
        </span>
        <span>
          <strong>prereq gate:</strong> {isPlatformTaskIntegrationReady() ? 'OFF' : 'ON'}
        </span>
        <span>
          <strong>parcel:</strong> @linm/message ChatSectionParcel
        </span>
        <span>
          <strong>routeMap:</strong> task=/platform-task/cv/:id · incident=/su-co/:id
        </span>
      </div>

      <section className={styles.card} data-des-id="DES-RTI-NAV">
        <h2>Công việc — nơi xem Task</h2>
        <p>
          Field (:9304) không host list/detail Task. Sau Giao việc: ở lại Field + mở ChatSectionParcel.
          Link «Mở Task MFE» → <code>http://localhost:8608/cv/:id</code>. :9302 là Gis, không phải Task.
        </p>
        <div className={styles.links}>
          <a className={styles.link} href={taskListHref} data-testid={`${TEST_ID}-open-task-list`}>
            <i className="fas fa-tasks" /> Danh sách công việc
          </a>
        </div>
      </section>

      <section className={styles.card} data-des-id="DES-RTI-CHAT">
        <h2>ChatSectionParcel — Message yarn start :8506</h2>
        <p>
          Mount cùng parcel Task MFE dùng. Cần Message <code>yarn start</code> (bundle, không{' '}
          <code>start:std</code>).
        </p>
        <div className={styles.mountRow}>
          <input
            value={taskIdInput}
            onChange={(e) => setTaskIdInput(e.target.value)}
            placeholder="taskId"
            data-testid={`${TEST_ID}-task-id`}
          />
          <Button
            variant="primary"
            size="sm"
            onClick={() => setMountedTaskId(taskIdInput.trim())}
            data-testid={`${TEST_ID}-mount-chat`}
          >
            Mount chat
          </Button>
        </div>
        {mountedTaskId ? (
          <div className={styles.hostWrap}>
            <ChatSectionHost taskId={mountedTaskId} onNavigate={onParcelNavigate} />
          </div>
        ) : null}
      </section>

      <section className={styles.card} data-des-id="DES-RTI-PATROL-FOOTER">
        <h2>Patrol — Giao việc</h2>
        <p>
          View mode → footer «Giao việc» → POST origin quad → toast → panel ChatSectionParcel + «Mở Task
          MFE». Không tự rời Field.
        </p>
        <div className={styles.links}>
          <Link className={styles.link} to="/td-tk">
            <i className="fas fa-route" /> Danh sách tuần tra
          </Link>
        </div>
      </section>

      <section className={styles.card} data-des-id="DES-RTI-INC-ACTION">
        <h2>Incident — Giao việc</h2>
        <p>View slideout hoặc row menu → shared modal → panel chat trên Field.</p>
        <div className={styles.links}>
          <Link className={styles.link} to="/su-co">
            <i className="fas fa-exclamation-triangle" /> Danh sách sự cố
          </Link>
        </div>
      </section>
    </div>
  );
};

export default RmmsTaskIntegrateVerifyPage;
